$ErrorActionPreference='Stop'; if (@(Get-ExecutionPolicy -List | Where-Object {$_.ExecutionPolicy -in @('AllSigned','Restricted')}).Count) {throw 'IT signing policy restricts this installer'}; [Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12; $jjDir=Join-Path $env:TEMP ('jjaitech-install-'+[guid]::NewGuid().ToString('N')); New-Item -ItemType Directory -Path $jjDir | Out-Null; $jjZip=Join-Path $jjDir 'release.zip'; for ($jjAttempt=1; $jjAttempt -le 3; $jjAttempt++) {try {Invoke-WebRequest -UseBasicParsing -Uri 'https://github.com/JachinLan/jjaitech-memory/releases/download/v1.4.1-rc.2-online.1/jjaitech-memory-1.4.1-rc.2-online.1.zip' -OutFile $jjZip -TimeoutSec 120; break} catch {if ($jjAttempt -eq 3) {throw}; Start-Sleep -Seconds 2}}; if ((Get-FileHash -Algorithm SHA256 -LiteralPath $jjZip).Hash.ToLowerInvariant() -ne '8922abe524e94f66b27305a92845b053d7258b1a891d21a6c0a4822d28393be2') {throw 'Download checksum mismatch; installation stopped'}; Expand-Archive -LiteralPath $jjZip -DestinationPath $jjDir; & ([scriptblock]::Create([IO.File]::ReadAllText((Join-Path $jjDir 'jjaitech-memory/distribution/bootstrap-windows.ps1')))) -PackageRoot $jjDir
